import discordfrom discord.ext import commandsasync def get_channel_by_name(guild: discord.Guild = commands.Parameter(name="guild", description="The server in which we get the channels from", kind=commands.Parameter.KEYWORD_ONLY),                              channel_name: str = commands.Parameter(name="channel_name", description="The channel in which you would like to search a guild for", kind=commands.Parameter.KEYWORD_ONLY)):    """    Retrieves a text channel by its name within a specific guild.    :param guild: The guild to search for the channel in.    :param channel_name: The name of the log channel to find.    :return:    """    if guild is None:        raise commands.MissingRequiredArgument(param=commands.Parameter('guild', commands.Parameter.KEYWORD_ONLY, description="The server in which we get the channels from."))    if channel_name is None:        raise commands.MissingRequiredArgument(param=commands.Parameter('channel_name', commands.Parameter.KEYWORD_ONLY, description="The channel in which you would like to search a guild for."))    for channel in guild.text_channels:        if channel.name == channel_name:            return channel    return None